var out=[];doc.pages.filter(function(p){return /^Proto macOS (Light|Dark)$/.test(p.name);}).forEach(function(p){p.layers.slice().forEach(function(s){if(/^caption:settings/.test(s.name))s.remove();if(/^Screen\/macos\/(Light|Dark)\/Clean\/settings/.test(s.name)){var texts=[],bad=[];function walk(l){if(/^link:/.test(l.name))l.name=l.name.replace(/ \d+$/,'');if(l.type==='Text')texts.push(l.text);(l.layers||[]).forEach(walk);}walk(s);var dt=s.layers.find(function(l){return l.name==='content-col';}).layers.find(function(l){return l.name==='main';}).layers.find(function(l){return l.name==='settings-split';}).layers.find(function(l){return l.name==='settings-detail';});out.push({id:s.name.split('/').pop(),app:p.name.replace('Proto macOS ',''),frame:s.id,width:s.frame.width,height:s.frame.height,x:s.frame.x,y:s.frame.y,sections:dt.layers.map(function(l){return l.name;}),headings:dt.layers.filter(function(l){return l.name==='detail-heading';}).length});}});});console.log(JSON.stringify(out));